import React, { useState, useEffect } from 'react'
import { supabase } from '../../lib/supabase'
import { useAuth } from '../../contexts/AuthContext'

export default function FollowButton({ userId, username, onFollowChange }) {
    const { user, profile } = useAuth()
    const [isFollowing, setIsFollowing] = useState(false)
    const [loading, setLoading] = useState(false)
    const [followersCount, setFollowersCount] = useState(0)

    useEffect(() => {
        checkFollowStatus()
        getFollowersCount()
    }, [userId])

    const checkFollowStatus = async () => {
        if (!user || userId === user.id) return
        
        try {
            const { data, error } = await supabase
                .from('followers')
                .select('*')
                .eq('follower_id', user.id)
                .eq('following_id', userId)
                .single()
            
            if (data) setIsFollowing(true)
        } catch (error) {
            // No follow relationship found
            setIsFollowing(false)
        }
    }

    const getFollowersCount = async () => {
        try {
            const { count } = await supabase
                .from('followers')
                .select('*', { count: 'exact', head: true })
                .eq('following_id', userId)
            
            setFollowersCount(count || 0)
        } catch (error) {
            console.error('Error getting followers count:', error)
        }
    }

    const handleFollow = async () => {
        if (!user) {
            alert('Please sign in to follow users')
            return
        }

        if (userId === user.id) {
            alert('You cannot follow yourself')
            return
        }

        setLoading(true)

        try {
            if (isFollowing) {
                // Unfollow
                const { error } = await supabase
                    .from('followers')
                    .delete()
                    .eq('follower_id', user.id)
                    .eq('following_id', userId)
                
                if (error) throw error
                setIsFollowing(false)
                setFollowersCount(prev => prev - 1)
                
                // Create notification
                await supabase.from('notifications').insert({
                    user_id: userId,
                    from_user_id: user.id,
                    type: 'unfollow',
                    message: `${profile?.username || 'Someone'} unfollowed you`
                })
            } else {
                // Follow
                const { error } = await supabase
                    .from('followers')
                    .insert({
                        follower_id: user.id,
                        following_id: userId
                    })
                
                if (error) throw error
                setIsFollowing(true)
                setFollowersCount(prev => prev + 1)
                
                // Create notification
                await supabase.from('notifications').insert({
                    user_id: userId,
                    from_user_id: user.id,
                    type: 'follow',
                    message: `${profile?.username || 'Someone'} started following you`
                })
            }

            if (onFollowChange) onFollowChange()
        } catch (error) {
            console.error('Follow error:', error)
            alert('Failed to follow/unfollow user')
        } finally {
            setLoading(false)
        }
    }

    // Don't show follow button for own profile
    if (!user || userId === user.id) return null

    return (
        <div className="flex items-center gap-3">
            <button
                onClick={handleFollow}
                disabled={loading}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                    isFollowing
                        ? 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        : 'bg-green-600 text-white hover:bg-green-700'
                } disabled:opacity-50`}
            >
                {loading ? '...' : isFollowing ? '✓ Following' : '+ Follow'}
            </button>
            <span className="text-sm text-gray-500">{followersCount} followers</span>
        </div>
    )
}
